INSERT INTO `tiket` VALUES (1,'BDG-20260914-001','Backbone : SW BBLU - SW Reog Down','SW BBLU - SW Reog','LOS pada segmen backbone BBLU arah Reog. Indikasi kabel putus di jalur crossing.','2026-09-14 21:00:00','2026-09-15 02:45:00','CLOSE',345,360,'TEPAT',2,2,'2026-09-21 10:04:08','2026-09-21 10:04:08'),(2,'BDG-20260915-001','Backbone : SW Cikutra - SW Dago High Latency & Packet Loss','SW Cikutra - SW Dago','Bending terdeteksi di KM 4.2. Redaman melonjak drastis hingga -28 dB.','2026-09-15 08:30:00','2026-09-15 16:00:00','CLOSE',450,360,'LEBIH',2,1,'2026-09-21 10:04:08','2026-09-21 10:04:08'),(3,'BDG-20260916-001','Segment : SW Pasteur - SW Sukajadi FO Cut','SW Pasteur - SW Sukajadi','Pekerjaan galian drainase kota mengenai kabel fiber optic 24 core.','2026-09-16 10:15:00','2026-09-16 13:30:00','CLOSE',195,240,'TEPAT',2,2,'2026-09-21 10:04:08','2026-09-21 10:04:08'),(4,'BDG-20260916-002','Backbone : SW Soekarno Hatta - SW Buah Batu Total Down','SW Soekarno Hatta - SW Buah Batu','Tiang miring tertabrak truk box di perempatan bypass.','2026-09-16 14:00:00','2026-09-16 19:00:00','CLOSE',300,360,'TEPAT',2,2,'2026-09-21 10:04:08','2026-09-21 10:04:08'),(5,'BDG-20260917-001','Segment : SW Kopo - SW Cibaduyut Core Degradation','SW Kopo - SW Cibaduyut','Redaman tinggi di closure lama dekat jembatan tol.','2026-09-17 09:00:00',NULL,'PROSES',NULL,180,'NA',2,NULL,'2026-09-21 10:04:08','2026-09-21 10:04:08'),(6,'BDG-20260917-002','Segment : SW Ujungberung - SW Cibiru Link Flapping','SW Ujungberung - SW Cibiru','Link sering up-down setiap 15 menit, indikasi patchcord kotor atau loose tube.','2026-09-17 13:30:00',NULL,'PROSES',NULL,180,'NA',2,NULL,'2026-09-21 10:04:08','2026-09-21 10:04:08'),(7,'BDG-20260918-001','Backbone : SW Cimahi - SW Padalarang Cut KM 11','SW Cimahi - SW Padalarang','Kabel 48 core putus tersangkut dahan pohon tumbang saat hujan lebat.','2026-09-18 06:15:00',NULL,'OPEN',NULL,240,'NA',2,NULL,'2026-09-21 10:04:08','2026-09-21 10:04:08'),(8,'BDG-20260918-002','